/*******************************************************************************
* File Name : main.c  (CM33 non-secure)
*
* Layer 3 - application. No CYBSP_* / Cy_* here.
*
* lvgl-ui-app: CM55 runs the UI designed in ui/ui.json (ui-designer skill,
* generated by ui_gen.py); CM33 owns the console, enables the graphics clocks
* before it starts CM55 and reads/drives the UI through the mailbox
* (IPC_CMD_GFX, IPC_CMD_UI - shared/ui_ids.h), so tests need nobody at the
* screen.
*
* Commands: info | ipc? | gfx | uptime55 | ui | uitree | uidata
*           uiset <data> <v> | uiget <data> | uiscreen <screen> | uiclick <widget>
*******************************************************************************/
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "board.h"
#include "bsp_status.h"
#include "console.h"
#include "display_clocks.h"
#include "ipc_client.h"
#define UI_IDS_NAMES                /* the name tables of ui_ids.h live in this file */
#include "ui_ids.h"

#define APP_NAME            "lvgl-ui-app"
#define APP_VERSION         "1.0"
#define CM55_READY_WAIT_MS  (500U)
#define HB_WINDOW_MS        (100U)

/* app command shared with proj_cm55/main.c: arg = field, result = value */
#define IPC_CMD_GFX         (IPC_CMD_APP_BASE + 0UL)
enum
{
    GFX_STATE = 0, GFX_DISPLAY, GFX_GPU, GFX_TOUCH, GFX_IRQS, GFX_FLUSHES, GFX_FRAME_MS,
    GFX_TIMEOUTS, GFX_PRESSES, GFX_TOUCH_XY, GFX_RSLT, GFX_TOUCH_ERRS, GFX_SHOW_MS, GFX_FIELDS
};

static const char *st_name(uint32_t v)
{
    return bsp_status_str((bsp_status_t)v);
}

/* one IPC_CMD_UI call; prints the error itself, returns false on failure */
static bool ui_call(uint32_t op, uint32_t idx, int32_t val, uint32_t *out)
{
    uint32_t rtt = 0UL;
    uint32_t st = ipc_client_call(IPC_CMD_UI, UI_ARG(op, idx, val), out, &rtt);
    if (IPC_OK != st)
    {
        printf("ERR ui op=%lu idx=%lu ipc status=%lu (display not up?)\r\n",
               (unsigned long)op, (unsigned long)idx, (unsigned long)st);
        return false;
    }
    return true;
}

static int find_name(const char *const *names, uint32_t count, const char *name)
{
    for (uint32_t i = 0U; i < count; i++)
    {
        if (0 == strcmp(names[i], name))
        {
            return (int)i;
        }
    }
    return -1;
}

static void print_info(void)
{
    printf("INFO app=%s v=%s board=%s cm55=%u ui=%s\r\n", APP_NAME, APP_VERSION, BOARD_NAME,
           ipc_client_ready() ? 1U : 0U, UI_SPEC_NAME);
    printf("READY\r\n");
}

static void cmd_info(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    print_info();
}

static void cmd_ipc(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    uint32_t hb0 = ipc_client_heartbeat();
    board_delay_ms(HB_WINDOW_MS);
    uint32_t hb1 = ipc_client_heartbeat();
    printf("IPC ready=%u alive=%u hb_per_s=%lu\r\n", ipc_client_ready() ? 1U : 0U,
           (hb1 != hb0) ? 1U : 0U, (unsigned long)((hb1 - hb0) * (1000U / HB_WINDOW_MS)));
}

static void cmd_uptime55(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    uint32_t v = 0UL, rtt = 0UL;
    uint32_t st = ipc_client_call(IPC_CMD_UPTIME, 0UL, &v, &rtt);
    if (IPC_OK == st)
    {
        printf("OK uptime55_ms=%lu cm33_ms=%lu\r\n", (unsigned long)v, (unsigned long)board_millis());
    }
    else
    {
        printf("ERR ipc status=%lu\r\n", (unsigned long)st);
    }
}

static void cmd_gfx(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    uint32_t v[GFX_FIELDS];
    for (uint32_t f = 0U; f < GFX_FIELDS; f++)
    {
        uint32_t rtt = 0UL;
        uint32_t st = ipc_client_call(IPC_CMD_GFX, f, &v[f], &rtt);
        if (IPC_OK != st)
        {
            printf("ERR gfx field=%lu ipc status=%lu (cm55 busy starting the display?)\r\n",
                   (unsigned long)f, (unsigned long)st);
            return;
        }
    }
    printf("GFX state=%s display=%s gpu=%s touch=%s irqs=%lu flushes=%lu render_ms=%lu "
           "show_ms=%lu timeouts=%lu rslt=0x%08lX\r\n",
           (1U == v[GFX_STATE]) ? "run" : ((0U == v[GFX_STATE]) ? "init" : "fail"),
           st_name(v[GFX_DISPLAY]), st_name(v[GFX_GPU]), st_name(v[GFX_TOUCH]),
           (unsigned long)v[GFX_IRQS], (unsigned long)v[GFX_FLUSHES], (unsigned long)v[GFX_FRAME_MS],
           (unsigned long)v[GFX_SHOW_MS], (unsigned long)v[GFX_TIMEOUTS], (unsigned long)v[GFX_RSLT]);
    printf("TOUCH presses=%lu x=%lu y=%lu errors=%lu\r\n", (unsigned long)v[GFX_PRESSES],
           (unsigned long)(v[GFX_TOUCH_XY] >> 16), (unsigned long)(v[GFX_TOUCH_XY] & 0xFFFFUL),
           (unsigned long)v[GFX_TOUCH_ERRS]);
}

static void cmd_ui(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    uint32_t n_s = 0UL, n_w = 0UL, n_d = 0UL, evs = 0UL, last = 0UL, act = 0UL;
    if (!ui_call(UI_OP_INFO, UI_INFO_SCREENS, 0, &n_s) || !ui_call(UI_OP_INFO, UI_INFO_WIDGETS, 0, &n_w) ||
        !ui_call(UI_OP_INFO, UI_INFO_DATA, 0, &n_d) || !ui_call(UI_OP_INFO, UI_INFO_EVENTS, 0, &evs) ||
        !ui_call(UI_OP_INFO, UI_INFO_LAST, 0, &last) || !ui_call(UI_OP_INFO, UI_INFO_ACTIVE, 0, &act))
    {
        return;
    }
    uint32_t lw = last >> 8, le = last & 0xFFUL;
    printf("UI name=%s screens=%lu widgets=%lu data=%lu events=%lu last=%s:%s active=%s\r\n",
           UI_SPEC_NAME, (unsigned long)n_s, (unsigned long)n_w, (unsigned long)n_d, (unsigned long)evs,
           (0UL == evs) ? "-" : ((lw < UI_WIDGET_COUNT) ? ui_widget_names[lw] : "?"),
           (0UL == evs) ? "-" : ((le < (sizeof(ui_event_names) / sizeof(ui_event_names[0]))) ? ui_event_names[le] : "?"),
           (act < UI_SCREEN_COUNT) ? ui_screen_names[act] : "?");
    if ((n_s != UI_SCREEN_COUNT) || (n_w != UI_WIDGET_COUNT) || (n_d != UI_DATA_COUNT))
    {
        printf("ERR ui_ids.h does not match CM55 (rebuild both cores after ui_gen.py)\r\n");
    }
}

static void cmd_uitree(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    for (uint32_t i = 0U; i < UI_WIDGET_COUNT; i++)
    {
        uint32_t xy = 0UL, wh = 0UL, fl = 0UL, val = 0UL;
        if (!ui_call(UI_OP_XY, i, 0, &xy) || !ui_call(UI_OP_WH, i, 0, &wh) ||
            !ui_call(UI_OP_FLAGS, i, 0, &fl) || !ui_call(UI_OP_VALUE, i, 0, &val))
        {
            return;
        }
        printf("UIW i=%lu id=%s type=%s scr=%s x=%d y=%d w=%lu h=%lu vis=%u act=%u in=%u val=%ld\r\n",
               (unsigned long)i, ui_widget_names[i], ui_type_names[ui_widget_types[i]],
               ui_screen_names[ui_widget_screen[i]], (int)(int16_t)(xy >> 16), (int)(int16_t)(xy & 0xFFFFUL),
               (unsigned long)(wh >> 16), (unsigned long)(wh & 0xFFFFUL),
               (0UL != (fl & UI_F_VISIBLE)) ? 1U : 0U, (0UL != (fl & UI_F_ACTIVE)) ? 1U : 0U,
               (0UL != (fl & UI_F_INSIDE)) ? 1U : 0U, (long)(int32_t)val);
    }
    printf("OK uitree widgets=%lu\r\n", (unsigned long)UI_WIDGET_COUNT);
}

static void cmd_uidata(int argc, char *argv[])
{
    (void)argc;
    (void)argv;
    for (uint32_t i = 0U; i < UI_DATA_COUNT; i++)
    {
        uint32_t v = 0UL;
        if (!ui_call(UI_OP_GET, i, 0, &v))
        {
            return;
        }
        printf("UID %s=%ld\r\n", ui_data_names[i], (long)(int32_t)v);
    }
    printf("OK uidata data=%lu\r\n", (unsigned long)UI_DATA_COUNT);
}

static void cmd_uiget(int argc, char *argv[])
{
    int d = (argc == 2) ? find_name(ui_data_names, UI_DATA_COUNT, argv[1]) : -1;
    uint32_t v = 0UL;
    if (d < 0)
    {
        printf("ERR usage: uiget <data> (see uidata)\r\n");
    }
    else if (ui_call(UI_OP_GET, (uint32_t)d, 0, &v))
    {
        printf("UID %s=%ld\r\n", ui_data_names[d], (long)(int32_t)v);
    }
}

static void cmd_uiset(int argc, char *argv[])
{
    int d = (argc == 3) ? find_name(ui_data_names, UI_DATA_COUNT, argv[1]) : -1;
    char *end = NULL;
    long v = (argc == 3) ? strtol(argv[2], &end, 0) : 0L;
    uint32_t now = 0UL;
    if ((d < 0) || (NULL == end) || ('\0' != *end) || (v < -32768L) || (v > 32767L))
    {
        printf("ERR usage: uiset <data> <-32768..32767>\r\n");
    }
    else if (ui_call(UI_OP_SET, (uint32_t)d, (int32_t)v, &now))
    {
        printf("OK uiset %s=%ld\r\n", ui_data_names[d], (long)(int32_t)now);   /* after clamping */
    }
}

static void cmd_uiscreen(int argc, char *argv[])
{
    int s = (argc == 2) ? find_name(ui_screen_names, UI_SCREEN_COUNT, argv[1]) : -1;
    uint32_t r = 0UL;
    if (s < 0)
    {
        printf("ERR usage: uiscreen <screen>\r\n");
    }
    else if (ui_call(UI_OP_SCREEN, (uint32_t)s, 0, &r))
    {
        printf("OK uiscreen %s\r\n", ui_screen_names[s]);
    }
}

static void cmd_uiclick(int argc, char *argv[])
{
    int w = (argc == 2) ? find_name(ui_widget_names, UI_WIDGET_COUNT, argv[1]) : -1;
    uint32_t r = 0UL;
    if (w < 0)
    {
        printf("ERR usage: uiclick <widget> (see uitree)\r\n");
    }
    else if (ui_call(UI_OP_CLICK, (uint32_t)w, 0, &r))
    {
        printf("OK uiclick %s\r\n", ui_widget_names[w]);
    }
}

static const console_cmd_t commands[] =
{
    { "info",     "info                  - app/board info + cm55 state", cmd_info },
    { "ipc?",     "ipc?                  - cm55 ready/alive, heartbeat rate", cmd_ipc },
    { "gfx",      "gfx                   - display/GPU/LVGL/touch status from cm55", cmd_gfx },
    { "uptime55", "uptime55              - cm55 millisecond tick", cmd_uptime55 },
    { "ui",       "ui                    - UI summary: counts, events, active screen", cmd_ui },
    { "uitree",   "uitree                - every widget: box, flags, value", cmd_uitree },
    { "uidata",   "uidata                - every data item", cmd_uidata },
    { "uiget",    "uiget <data>          - one data item", cmd_uiget },
    { "uiset",    "uiset <data> <v>      - set a data item (bound widgets follow)", cmd_uiset },
    { "uiscreen", "uiscreen <screen>     - load a screen", cmd_uiscreen },
    { "uiclick",  "uiclick <widget>      - send a click event to a widget", cmd_uiclick },
};

int main(void)
{
    board_init();
    console_init(commands, sizeof(commands) / sizeof(commands[0]));

    printf("\r\n[APP] %s %s on %s, ui %s\r\n", APP_NAME, APP_VERSION, BOARD_NAME, UI_SPEC_NAME);

    display_clocks_enable();      /* GFXSS clocks: before CM55 touches the display */
    ipc_client_init();            /* must be valid before CM55 runs */
    board_start_cm55();

    uint32_t t0 = board_millis();
    while (!ipc_client_ready() && ((board_millis() - t0) < CM55_READY_WAIT_MS))
    {
    }
    if (!ipc_client_ready())
    {
        printf("ERR cm55 not ready after %u ms\r\n", (unsigned)CM55_READY_WAIT_MS);
    }
    print_info();

    for (;;)
    {
        console_poll();
    }
}
